		if tt.expected != nil {
			expected = tt.expected()
		}

		t.Run(tt.name+" (YAML)", func(t *testing.T) {
			result, err := Load(path)

			if wantErr != nil {
				t.Log(err)
				require.ErrorIs(t, err, wantErr)
				assert.Nil(t, result)
				return
			}

			require.NoError(t, err)

			require.NotNil(t, result)
			assert.Equal(t, expected, result.Config)
			assert.Equal(t, tt.wantWarnings, result.Warnings)
		})

		t.Run(tt.name+" (ENV)", func(t *testing.T) {
			// backup and restore environment
			backup := os.Environ()
			defer func() {
				os.Clearenv()
				for _, env := range backup {
					key, value, _ := strings.Cut(env, "=")
					os.Setenv(key, value)
				}
			}()

			// read the input config file into equivalent envs
			envs := readYAMLIntoEnv(t, path)
			for _, env := range envs {
				t.Logf("Setting env '%s=%s'\n", env[0], env[1])
				os.Setenv(env[0], env[1])
			}

			// load default (empty) config
			result, err := Load("./testdata/default.yml")

			if wantErr != nil {
				t.Log(err)
				require.ErrorIs(t, err, wantErr)
				assert.Nil(t, result)
				return
			}

			require.NoError(t, err)

			require.NotNil(t, result)
			assert.Equal(t, expected, result.Config)
			assert.Empty(t, result.Warnings)
		})
	}
